package com.smartexam.service;

import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper;
import com.smartexam.common.ErrorCode;import com.smartexam.dto.MvpRequests;import com.smartexam.entity.*;import com.smartexam.exception.BusinessException;import com.smartexam.vo.MvpViews;import com.smartexam.vo.TeacherViews;import lombok.RequiredArgsConstructor;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import org.apache.poi.ss.usermodel.*;import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import java.io.ByteArrayOutputStream;import java.io.IOException;
import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.*;

@Service @RequiredArgsConstructor public class TeacherGradingService {
 private final UsersService users;private final CoursesService courses;private final ExamsService exams;private final QuestionsService questions;private final ScoringPointsService points;private final SubmissionsService submissions;private final AnswersService answers;private final AiGradingResultsService aiResults;private final AiGradingService ai;private final StudentExamService studentExams;
 private Users teacher(String name){Users u=users.findByUsername(name);if(u==null||!Integer.valueOf(1).equals(u.getStatus()))throw fail(HttpStatus.UNAUTHORIZED,"请先登录");if(!"TEACHER".equals(u.getRole()))throw fail(HttpStatus.FORBIDDEN,"无权限访问");return u;}
 private Exams ownExam(String name,Long id){Users u=teacher(name);Exams e=exams.getById(id);if(e==null)throw fail(HttpStatus.NOT_FOUND,"考试不存在");Courses c=courses.getById(e.getCourseId());if(c==null||!Objects.equals(c.getTeacherId(),u.getId()))throw fail(HttpStatus.FORBIDDEN,"无权限访问其他教师的数据");return e;}
 private Exams lockOwnExam(String name,Long id){Users u=teacher(name);Exams e=exams.lockById(id);if(e==null)throw fail(HttpStatus.NOT_FOUND,"考试不存在");Courses c=courses.getById(e.getCourseId());if(c==null||!Objects.equals(c.getTeacherId(),u.getId()))throw fail(HttpStatus.FORBIDDEN,"无权限访问其他教师的数据");return e;}
 private Submissions ownSubmission(String name,Long id){Submissions s=submissions.getById(id);if(s==null)throw fail(HttpStatus.NOT_FOUND,"答卷不存在");ownExam(name,s.getExamId());if("IN_PROGRESS".equals(s.getStatus()))throw fail(HttpStatus.CONFLICT,"学生尚未交卷");return s;}
 public List<MvpViews.ReviewExam> exams(String name){Users u=teacher(name);return courses.findByTeacherId(u.getId()).stream().flatMap(c->exams.findByCourseId(c.getId()).stream().filter(e->!"DRAFT".equals(e.getStatus())).map(e->{List<Submissions> rows=submissions.findByExamId(e.getId());return new MvpViews.ReviewExam(e.getId(),c.getCourseName(),e.getTitle(),e.getStatus(),e.getEndTime(),rows.size(),rows.stream().filter(s->!"GRADED".equals(s.getStatus())).count(),rows.stream().filter(s->"GRADED".equals(s.getStatus())).count());})).sorted(Comparator.comparing(MvpViews.ReviewExam::id).reversed()).toList();}
 public List<MvpViews.ReviewSubmission> submissions(String name,Long examId){ownExam(name,examId);Set<Long> pendingManual=answers.pendingManualReviewSubmissionIds(examId);return submissions.findByExamId(examId).stream().filter(s->!"IN_PROGRESS".equals(s.getStatus())).map(s->new MvpViews.ReviewSubmission(s.getId(),s.getStudentId(),users.getById(s.getStudentId()).getName(),s.getStatus(),gradingStatus(s,pendingManual.contains(s.getId())),s.getSubmitTime(),s.getTotalScore(),Integer.valueOf(1).equals(s.getScorePublished()),pendingManual.contains(s.getId()))).toList();}
 public MvpViews.ReviewPaper paper(String name,Long id){Submissions s=ownSubmission(name,id);Exams e=exams.getById(s.getExamId());List<MvpViews.ReviewAnswer> rows=answers.findBySubmissionId(id).stream().map(a->{Questions q=questions.getById(a.getQuestionId());AiGradingResults ar=aiResults.findByAnswerId(a.getId());MvpViews.AiSuggestion suggestion=ar==null?null:new MvpViews.AiSuggestion(ar.getStatus(),ar.getAiScore(),ar.getAiReason(),ar.getAiComment(),ai.strings(ar.getMatchedPoints()),ai.strings(ar.getMissingPoints()),ar.getErrorMessage());return new MvpViews.ReviewAnswer(a.getId(),q.getId(),q.getQuestionType(),q.getContent(),q.getScore(),q.getReferenceAnswer(),points.findByQuestionId(q.getId()).stream().map(p->new TeacherViews.Point(p.getId(),p.getPointContent(),p.getPointScore(),p.getSortOrder())).toList(),a.getAnswerContent(),a.getAutoScore(),a.getTeacherScore(),a.getTeacherComment(),a.getGradingStatus(),suggestion);}).toList();return new MvpViews.ReviewPaper(s.getId(),e.getId(),e.getTitle(),users.getById(s.getStudentId()).getName(),s.getStatus(),s.getSubmitTime(),s.getTotalScore(),s.getTeacherComment(),Integer.valueOf(1).equals(s.getScorePublished()),s.getPublishedAt(),rows);}
 public ExportFile exportResults(String name,Long examId){Exams exam=ownExam(name,examId);try(XSSFWorkbook workbook=new XSSFWorkbook();ByteArrayOutputStream output=new ByteArrayOutputStream()){Sheet sheet=workbook.createSheet("成绩");CellStyle headerStyle=workbook.createCellStyle();Font headerFont=workbook.createFont();headerFont.setBold(true);headerStyle.setFont(headerFont);String[] headers={"学号","姓名","考试名称","客观题得分","简答题最终得分","最终总分","教师最终评语","成绩状态","成绩发布时间"};Row header=sheet.createRow(0);for(int i=0;i<headers.length;i++){Cell cell=header.createCell(i);cell.setCellValue(headers[i]);cell.setCellStyle(headerStyle);}int rowIndex=1;for(Submissions submission:submissions.findByExamId(examId)){if("IN_PROGRESS".equals(submission.getStatus()))continue;BigDecimal objective=BigDecimal.ZERO,shortScore=BigDecimal.ZERO;for(Answers answer:answers.findBySubmissionId(submission.getId())){Questions question=questions.getById(answer.getQuestionId());if(question==null)continue;if("SINGLE_CHOICE".equals(question.getQuestionType()))objective=objective.add(zero(answer.getAutoScore()));else if("SHORT_ANSWER".equals(question.getQuestionType()))shortScore=shortScore.add(zero(answer.getTeacherScore()));}Users student=users.getById(submission.getStudentId());Row row=sheet.createRow(rowIndex++);text(row,0,student==null?"":student.getUsername());text(row,1,student==null?"":student.getName());text(row,2,exam.getTitle());number(row,3,objective);number(row,4,shortScore);number(row,5,zero(submission.getTotalScore()));text(row,6,submission.getTeacherComment());text(row,7,Integer.valueOf(1).equals(submission.getScorePublished())?"已发布":"未发布");if(submission.getPublishedAt()!=null)row.createCell(8).setCellValue(submission.getPublishedAt());}int[] widths={18,16,28,14,18,14,30,12,20};for(int i=0;i<widths.length;i++)sheet.setColumnWidth(i,widths[i]*256);workbook.write(output);return new ExportFile(output.toByteArray(),safeFileName(exam.getTitle())+"_成绩.xlsx");}catch(IOException e){throw new IllegalStateException("生成成绩文件失败",e);}}
 private static BigDecimal zero(BigDecimal value){return value==null?BigDecimal.ZERO:value;}
 private static void text(Row row,int column,String value){row.createCell(column).setCellValue(value==null?"":value);}
 private static void number(Row row,int column,BigDecimal value){row.createCell(column).setCellValue(value.doubleValue());}
 private static String safeFileName(String title){String safe=title==null?"考试":title.replaceAll("[\\\\/:*?\"<>|]","_").trim();return safe.isEmpty()?"考试":safe;}
 public record ExportFile(byte[] content,String fileName){}
 @Transactional public MvpViews.ReviewPaper requestAi(String name,Long answerId){Answers a=answers.getById(answerId);if(a==null)throw fail(HttpStatus.NOT_FOUND,"答案不存在");Submissions s=lock(ownSubmission(name,a.getSubmissionId()));ensureUnpublished(s);Questions q=questions.getById(a.getQuestionId());if(!"SHORT_ANSWER".equals(q.getQuestionType()))throw fail(HttpStatus.BAD_REQUEST,"只有简答题支持 AI 阅卷");ai.grade(a,q);return paper(name,s.getId());}
 @Transactional public MvpViews.ReviewPaper review(String name,Long answerId,MvpRequests.ReviewAnswer r){Answers a=answers.getById(answerId);if(a==null)throw fail(HttpStatus.NOT_FOUND,"答案不存在");Submissions s=lock(ownSubmission(name,a.getSubmissionId()));ensureUnpublished(s);Questions q=questions.getById(a.getQuestionId());if(!"SHORT_ANSWER".equals(q.getQuestionType()))throw fail(HttpStatus.BAD_REQUEST,"单选题使用系统自动评分，不支持人工改分");if(r.teacherScore().compareTo(q.getScore())>0)throw fail(HttpStatus.BAD_REQUEST,"教师评分不能超过题目分值");a.setTeacherScore(r.teacherScore());a.setTeacherComment(r.teacherComment());a.setGradingStatus("REVIEWED");answers.updateById(a);recalculate(s);return paper(name,s.getId());}
 @Transactional public MvpViews.ReviewPaper comment(String name,Long id,MvpRequests.SubmissionComment r){Submissions s=lock(ownSubmission(name,id));ensureUnpublished(s);s.setTeacherComment(r.teacherComment());submissions.updateById(s);return paper(name,id);}
 private void recalculate(Submissions s){List<Answers> rows=answers.findBySubmissionId(s.getId());BigDecimal total=rows.stream().map(a->{Questions q=questions.getById(a.getQuestionId());BigDecimal score="SINGLE_CHOICE".equals(q.getQuestionType())?a.getAutoScore():a.getTeacherScore();return score==null?BigDecimal.ZERO:score;}).reduce(BigDecimal.ZERO,BigDecimal::add);s.setTotalScore(total);long questionCount=questions.count(new QueryWrapper<Questions>().eq("exam_id",s.getExamId()));if(rows.size()==questionCount&&rows.stream().allMatch(a->"REVIEWED".equals(a.getGradingStatus())||("SINGLE_CHOICE".equals(questions.getById(a.getQuestionId()).getQuestionType())&&"AUTO_GRADED".equals(a.getGradingStatus()))))s.setStatus("GRADED");submissions.updateById(s);}
 @Transactional public MvpViews.ReviewPaper publish(String name,Long id){ownSubmission(name,id);throw fail(HttpStatus.CONFLICT,"成绩必须按整场考试统一发布");}
 @Transactional public void publishExamResults(String name,Long examId){LocalDateTime now=LocalDateTime.now();Exams exam=lockOwnExam(name,examId);if("DRAFT".equals(exam.getStatus()))throw fail(HttpStatus.CONFLICT,"草稿考试不能发布成绩");if(exam.getResultsReleasedAt()!=null)throw fail(HttpStatus.CONFLICT,"成绩已经发布");if(now.isBefore(exam.getEndTime()))throw fail(HttpStatus.CONFLICT,"考试尚未结束");List<Submissions> rows=studentExams.autoSubmitExpiredForExam(exam,now);for(Submissions row:rows)recalculate(row);rows=submissions.lockByExamId(examId);long inProgress=rows.stream().filter(s->"IN_PROGRESS".equals(s.getStatus())).count();if(inProgress>0)throw fail(HttpStatus.CONFLICT,"存在 "+inProgress+" 份未完成自动提交处理的答卷");long pending=rows.stream().filter(s->!"GRADED".equals(s.getStatus())).count();if(pending>0)throw fail(HttpStatus.CONFLICT,"还有 "+pending+" 份答卷未完成阅卷");for(Submissions row:rows){row.setScorePublished(1);if(row.getPublishedAt()==null)row.setPublishedAt(now);submissions.updateById(row);}exam.setResultsReleasedAt(now);exams.updateById(exam);}
 private String gradingStatus(Submissions s,boolean pendingManual){return Integer.valueOf(1).equals(s.getScorePublished())?"PUBLISHED":pendingManual?"PENDING":"GRADED".equals(s.getStatus())?"REVIEWED":"AUTO_GRADED";}
 private void ensureUnpublished(Submissions s){Exams exam=exams.getById(s.getExamId());if((exam!=null&&exam.getResultsReleasedAt()!=null)||Integer.valueOf(1).equals(s.getScorePublished()))throw fail(HttpStatus.CONFLICT,"成绩已发布，禁止继续修改");}
 private Submissions lock(Submissions s){Submissions locked=submissions.lockById(s.getId());return locked==null?s:locked;}
 private static BusinessException fail(HttpStatus s,String m){return new BusinessException(s,s==HttpStatus.NOT_FOUND?ErrorCode.NOT_FOUND:s==HttpStatus.FORBIDDEN?ErrorCode.FORBIDDEN:s==HttpStatus.UNAUTHORIZED?ErrorCode.UNAUTHORIZED:s==HttpStatus.BAD_REQUEST?ErrorCode.BAD_REQUEST:ErrorCode.CONFLICT,m);}
}
